from .hardware import Quanta, Dell
from .commands import SystemVersionCommand


def find_switch_type(remote_shell):
    """ Find the switch type based on the output of 'show version' command.

    This function is meant to be used as a substitute for an instance of Switch
    in the argument to connect() function, e.g.:

        connect(find_switch_type, '1.2.3.4', 'admin', 'password')

    :param remote_shell: An instance of RemoteShell.
    :returns: A subclass of Switch.
    """
    remote_shell.connect()
    remote_shell.expect_exact('#')
    remote_shell.sendline('terminal length 0')
    remote_shell.expect_exact('#')

    cmd = SystemVersionCommand(remote_shell)
    output = cmd()
    remote_shell.disconnect()

    if "QUANTA" in output:
        switch_class = Quanta
    elif "S4048" in output:
        switch_class = Dell
    else:
        raise RuntimeError("cannot infer switch type.")

    return switch_class(remote_shell)
